(4340588, 625791, 70689, '<td valign="top">I hate your frame, but I lover the pic. Great how you captured the glass texture!</td>', 'I hate your frame, but I lover the pic. Great how you captured the glass texture!', '2007-12-28 07:37:16.000000', NULL, 1),
(4340589, 625798, 70689, '<td valign="top">Would have been better with the focus on the icicle.</td>', 'Would have been better with the focus on the icicle.', '2007-12-28 07:40:16.000000', NULL, 1),
(4340603, 625490, 5364, '<td valign="top">It''s too indistinct - all soft focus</td>', 'It''s too indistinct - all soft focus', '2007-12-28 08:12:42.000000', NULL, 1),
(4340605, 624430, 5364, '<td valign="top">Good idea to photograph a cauliflower, but the background lets you down. It might have been better if you had wrapped it under the cauliflower as well, so you had a smooth transition from "floor" to "wall".</td>', 'Good idea to photograph a cauliflower, but the background lets you down. It might have been better if you had wrapped it under the cauliflower as well, so you had a smooth transition from "floor" to "wall".', '2007-12-28 08:16:00.000000', NULL, 1),
(4340607, 625494, 5364, '<td valign="top">It looks a bit soft focus, and a darker background might have helped</td>', 'It looks a bit soft focus, and a darker background might have helped', '2007-12-28 08:17:30.000000', NULL, 1),
(4340612, 623980, 5364, '<td valign="top">It''s a bit confused - your title also says you don''t know what the subject is</td>', 'It''s a bit confused - your title also says you don''t know what the subject is', '2007-12-28 08:18:53.000000', NULL, 1),
(4340618, 625267, 5364, '<td valign="top">If had been in focus and a tighter crop, then maybe you would do better</td>', 'If had been in focus and a tighter crop, then maybe you would do better', '2007-12-28 08:20:51.000000', NULL, 1),
(4340621, 625662, 5364, '<td valign="top">It''s good, but would it be better if the ripples were at an angle, rather than running vertically as in your image?</td>', 'It''s good, but would it be better if the ripples were at an angle, rather than running vertically as in your image?', '2007-12-28 08:23:09.000000', NULL, 1),
(4340623, 625341, 5364, '<td valign="top">Nice idea, but it''s too out of focus and you might get more texture with the light coming from the side, rather than from the front.</td>', 'Nice idea, but it''s too out of focus and you might get more texture with the light coming from the side, rather than from the front.', '2007-12-28 08:24:39.000000', NULL, 1),
(4340628, 624836, 5364, '<td valign="top">Unfortunately it''s not the snow that catches the eye but the bright sun. It''s a good idea though.</td>', 'Unfortunately it''s not the snow that catches the eye but the bright sun. It''s a good idea though.', '2007-12-28 08:26:31.000000', NULL, 1),
(4340630, 624350, 5364, '<td valign="top">the lighting is a bit flat on this so it doesn''t accentuate the textures</td>', 'the lighting is a bit flat on this so it doesn''t accentuate the textures', '2007-12-28 08:28:28.000000', NULL, 1),
(4340633, 625772, 5364, '<td valign="top">I can''t help thinking the ladybird should be facing the camera</td>', 'I can''t help thinking the ladybird should be facing the camera', '2007-12-28 08:29:11.000000', NULL, 1),
(4340634, 625634, 5364, '<td valign="top">The foreground cactus doesn''t really stand out from the background enough</td>', 'The foreground cactus doesn''t really stand out from the background enough', '2007-12-28 08:30:06.000000', NULL, 1),
(4340639, 625340, 5364, '<td valign="top">It''s a good picture, I just find the obviously cut grass distracting - it''s got square ends!</td>', 'It''s a good picture, I just find the obviously cut grass distracting - it''s got square ends!', '2007-12-28 08:32:05.000000', NULL, 1),
(4340643, 625446, 5364, '<td valign="top">A close up on the texture of the bird box would improve this for me</td>', 'A close up on the texture of the bird box would improve this for me', '2007-12-28 08:34:59.000000', NULL, 1),
(4340653, 624464, 5364, '<td valign="top">I find the reflections on the forehead a bit distracting</td>', 'I find the reflections on the forehead a bit distracting', '2007-12-28 08:40:03.000000', NULL, 1),
(4340654, 625501, 5364, '<td valign="top">A good idea, but it''s a bit too small and out of focus</td>', 'A good idea, but it''s a bit too small and out of focus', '2007-12-28 08:40:41.000000', NULL, 1),
(4340675, 624167, 67258, '<td valign="top">A lovely photo, but probably better suited to the Free Study rather than the ''TEXTURE'' challenge, as the rendition of the texture of the leopards''s fur is, in my opinion, the weakest area of this photo.</td>', 'A lovely photo, but probably better suited to the Free Study rather than the ''TEXTURE'' challenge, as the rendition of the texture of the leopards''s fur is, in my opinion, the weakest area of this photo.', '2007-12-28 08:54:39.000000', NULL, 1),
(4340736, 624971, 5364, '<td valign="top">uninspiring</td>', 'uninspiring', '2007-12-28 09:15:49.000000', NULL, 1),
(4340743, 624645, 5364, '<td valign="top">I just looks rather out of focus</td>', 'I just looks rather out of focus', '2007-12-28 09:17:13.000000', NULL, 1),
(4340748, 625258, 5364, '<td valign="top">But it doesn''t look smooth, or textured much for that matter. If you want smooth you need less direction lighting and probably warmer colour.</td>', 'But it doesn''t look smooth, or textured much for that matter. If you want smooth you need less direction lighting and probably warmer colour.', '2007-12-28 09:20:29.000000', NULL, 1),
(4340751, 625779, 5364, '<td valign="top">What is the texture you are making as you subject? It''s a bit confused.</td>', 'What is the texture you are making as you subject? It''s a bit confused.', '2007-12-28 09:21:24.000000', NULL, 1),
(4340752, 625752, 5364, '<td valign="top">It''s odd but I find the purple light offputting</td>', 'It''s odd but I find the purple light offputting', '2007-12-28 09:21:28.000000', NULL, 1),
(4340754, 625198, 5364, '<td valign="top">A close-up on the snow over your boots might have been more interesting</td>', 'A close-up on the snow over your boots might have been more interesting', '2007-12-28 09:22:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4340756, 623936, 5364, '<td valign="top">It doesn''t have much interest to me. Your title suggests there is a story here, but it''s not at all clear what that story is.</td>', 'It doesn''t have much interest to me. Your title suggests there is a story here, but it''s not at all clear what that story is.', '2007-12-28 09:24:04.000000', NULL, 1),
(4340758, 624390, 5364, '<td valign="top">I like the colours, but it''s not an interestingly textured subject.</td>', 'I like the colours, but it''s not an interestingly textured subject.', '2007-12-28 09:25:36.000000', NULL, 1),
(4340761, 625465, 5364, '<td valign="top">this isn''t an interesting image. Personally I quite like a close-up on the gravel - especially as it looks like you had a strong directional light from the sun.</td>', 'this isn''t an interesting image. Personally I quite like a close-up on the gravel - especially as it looks like you had a strong directional light from the sun.', '2007-12-28 09:28:00.000000', NULL, 1),
(4340762, 624179, 5364, '<td valign="top">If you had got the whole leaf in focus, and only had that leaf in colour, you would have got a better image.</td>', 'If you had got the whole leaf in focus, and only had that leaf in colour, you would have got a better image.', '2007-12-28 09:29:19.000000', NULL, 1),
(4340765, 625734, 5364, '<td valign="top">this looks rather washed-out and shiny metal doesn''t lend itself to an examination of texture.</td>', 'this looks rather washed-out and shiny metal doesn''t lend itself to an examination of texture.', '2007-12-28 09:31:00.000000', NULL, 1),
(4340771, 624449, 5364, '<td valign="top">Unfortunately it''s been done too many times before, and it''s never been very interesting. You might improve it a little by having the keys running diagonally across the image, rather than vertically.</td>', 'Unfortunately it''s been done too many times before, and it''s never been very interesting. You might improve it a little by having the keys running diagonally across the image, rather than vertically.', '2007-12-28 09:33:42.000000', NULL, 1),
(4340776, 624547, 5364, '<td valign="top">You usually need to get the eye in focus for animal shots, but your image is focused further down.</td>', 'You usually need to get the eye in focus for animal shots, but your image is focused further down.', '2007-12-28 09:35:17.000000', NULL, 1),
(4340778, 625834, 5364, '<td valign="top">It''s a bit too soft an image for my tastes</td>', 'It''s a bit too soft an image for my tastes', '2007-12-28 09:35:51.000000', NULL, 1),
(4340783, 624718, 5364, '<td valign="top">More of a focus on the spiky things would be to my preference - the orange flower is just getting in the way</td>', 'More of a focus on the spiky things would be to my preference - the orange flower is just getting in the way', '2007-12-28 09:37:20.000000', NULL, 1),
(4340788, 625439, 5364, '<td valign="top">Nice simple photo, but not conveying much in the way of texture</td>', 'Nice simple photo, but not conveying much in the way of texture', '2007-12-28 09:38:30.000000', NULL, 1),
(4340796, 625798, 5364, '<td valign="top">What texture are you trying to convey? There is too much movement for the shutter speed - everything is a bit fuzzy.</td>', 'What texture are you trying to convey? There is too much movement for the shutter speed - everything is a bit fuzzy.', '2007-12-28 09:42:30.000000', NULL, 1),
(4340797, 625270, 5364, '<td valign="top">The red is a bit overpowering and distracts from the texture of the broccoli</td>', 'The red is a bit overpowering and distracts from the texture of the broccoli', '2007-12-28 09:43:41.000000', NULL, 1),
(4340799, 624241, 5364, '<td valign="top">Its a bit too translucent to give a good impression of the texture</td>', 'Its a bit too translucent to give a good impression of the texture', '2007-12-28 09:44:11.000000', NULL, 1),
(4340800, 625672, 5364, '<td valign="top">The dog''s face shows lots of texture, but the background dominates as it''s so much brighter</td>', 'The dog''s face shows lots of texture, but the background dominates as it''s so much brighter', '2007-12-28 09:46:02.000000', NULL, 1),
