(4343965, 624651, 67547, '<td valign="top">beautiful picture. i predict a ribbon. 8</td>', 'beautiful picture. i predict a ribbon. 8', '2007-12-29 21:31:56.000000', NULL, 1),
(4344182, 625267, 24974, '<td valign="top">This doesn''t look to be in focus.</td>', 'This doesn''t look to be in focus.', '2007-12-29 22:54:53.000000', NULL, 1),
(4344186, 625756, 24974, '<td valign="top">Um...I don''t get the title. Pretty mountains, though.</td>', 'Um...I don''t get the title. Pretty mountains, though.', '2007-12-29 22:57:02.000000', NULL, 1),
(4344190, 624035, 24974, '<td valign="top">The colors in this shot are very muted for such bright subjects. There is not enough contrast.</td>', 'The colors in this shot are very muted for such bright subjects. There is not enough contrast.', '2007-12-29 22:59:46.000000', NULL, 1),
(4344201, 625505, 24974, '<td valign="top">The shot for me would have been better without the sea critter or whatever it is. The texture of the sand and relatively shallow depth of field make for a better picture by them selves in my opinion.</td>', 'The shot for me would have been better without the sea critter or whatever it is. The texture of the sand and relatively shallow depth of field make for a better picture by them selves in my opinion.', '2007-12-29 23:03:46.000000', NULL, 1),
(4344208, 625550, 24974, '<td valign="top">Very nice. 9</td>', 'Very nice. 9', '2007-12-29 23:06:53.000000', NULL, 1),
(4344209, 625490, 24974, '<td valign="top">Um...OK.</td>', 'Um...OK.', '2007-12-29 23:07:27.000000', NULL, 1),
(4344215, 624558, 24974, '<td valign="top">Very cool. Love the color too.</td>', 'Very cool. Love the color too.', '2007-12-29 23:12:01.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4344220, 624722, 24974, '<td valign="top">Is that a word? You''re right, it DOES look knobbly.  ;-)</td>', 'Is that a word? You''re right, it DOES look knobbly.  ;-)', '2007-12-29 23:13:48.000000', NULL, 1),
(4344226, 625534, 24974, '<td valign="top">Wow, how vivid! Love it. 9.</td>', 'Wow, how vivid! Love it. 9.', '2007-12-29 23:16:33.000000', NULL, 1),
(4344228, 625754, 24974, '<td valign="top">The colors look wrong but it is a neat shot.</td>', 'The colors look wrong but it is a neat shot.', '2007-12-29 23:17:49.000000', NULL, 1),
(4344237, 625643, 24974, '<td valign="top">How wonderful.</td>', 'How wonderful.', '2007-12-29 23:22:26.000000', NULL, 1),
(4344239, 624241, 24974, '<td valign="top">You know, I never realized how wrong a lime looks in black and white. It looks a little alien.</td>', 'You know, I never realized how wrong a lime looks in black and white. It looks a little alien.', '2007-12-29 23:23:20.000000', NULL, 1),
(4344242, 625812, 24974, '<td valign="top">Very nice. I can almost feel the texture.</td>', 'Very nice. I can almost feel the texture.', '2007-12-29 23:27:22.000000', NULL, 1),
(4344514, 625595, 82814, '<td valign="top">The colour is quite beautiful and the overall image is striking (no pun intended).</td>', 'The colour is quite beautiful and the overall image is striking (no pun intended).', '2007-12-30 04:41:44.000000', NULL, 1),
(4344518, 625560, 82814, '<td valign="top">I like the colour &amp; texture here.  This is a good example of contrast emphasizing the subject.  I''m not crazy about the table the bear is sitting on in this image - to me it is distracting.</td>', 'I like the colour & texture here.  This is a good example of contrast emphasizing the subject.  I''m not crazy about the table the bear is sitting on in this image - to me it is distracting.', '2007-12-30 04:51:36.000000', NULL, 1),
(4344519, 625345, 82814, '<td valign="top">Simplicity speaks volumes here.  Well done.</td>', 'Simplicity speaks volumes here.  Well done.', '2007-12-30 04:52:42.000000', NULL, 1),
(4344520, 625598, 82814, '<td valign="top">Beautifully captured.  How you made a snail look attractive is a talent in itself.</td>', 'Beautifully captured.  How you made a snail look attractive is a talent in itself.', '2007-12-30 04:55:14.000000', NULL, 1),
(4344527, 624514, 82814, '<td valign="top">Only a true photog would attempt a capture of muddy tire tracks.  Only a true photog could make this a worthy capture, as you have done here.  My only critique is that I would prefer this image be sharper.  Well done.</td>', 'Only a true photog would attempt a capture of muddy tire tracks.  Only a true photog could make this a worthy capture, as you have done here.  My only critique is that I would prefer this image be sharper.  Well done.', '2007-12-30 05:00:31.000000', NULL, 1),
(4344531, 625720, 67258, '<td valign="top">Perfect!</td>', 'Perfect!', '2007-12-30 05:02:47.000000', NULL, 1),
(4344533, 625773, 82814, '<td valign="top">I love this image.  I personally would have cropped out the top of this image and left it only as a water shot, but either way it''s very beautiful.</td>', 'I love this image.  I personally would have cropped out the top of this image and left it only as a water shot, but either way it''s very beautiful.', '2007-12-30 05:02:52.000000', NULL, 1),
(4344534, 625340, 82814, '<td valign="top">It looks like the entrance to the mushroom agridome. LOL.  Nice detail on the fungi texture and grass blades.  Nice DOF.</td>', 'It looks like the entrance to the mushroom agridome. LOL.  Nice detail on the fungi texture and grass blades.  Nice DOF.', '2007-12-30 05:06:01.000000', NULL, 1),
(4344536, 625763, 82814, '<td valign="top">Interesting result converting to negative.</td>', 'Interesting result converting to negative.', '2007-12-30 05:10:46.000000', NULL, 1),
(4344539, 625161, 82814, '<td valign="top">Love the title.  Love the texture and colour.  Shifting the angle of the shot may have eliminated the distracting upper right corner, but that may also not have been possible at the time of the capture.  Just a thought.</td>', 'Love the title.  Love the texture and colour.  Shifting the angle of the shot may have eliminated the distracting upper right corner, but that may also not have been possible at the time of the capture.  Just a thought.', '2007-12-30 05:14:47.000000', NULL, 1),
(4344542, 625843, 82814, '<td valign="top">It''s also a macro mystery!  I couldn''t figure out what this was.  Lots of detail and colour.  Could be a little bit sharper.</td>', 'It''s also a macro mystery!  I couldn''t figure out what this was.  Lots of detail and colour.  Could be a little bit sharper.', '2007-12-30 05:19:51.000000', NULL, 1),
(4344543, 625746, 82814, '<td valign="top">Fascinating capture.  Love the DOF here and the different levels of green.  Well done.</td>', 'Fascinating capture.  Love the DOF here and the different levels of green.  Well done.', '2007-12-30 05:20:52.000000', NULL, 1),
(4344545, 625817, 82814, '<td valign="top">This is a 10 for me.  The DOF is superb.  Love it.</td>', 'This is a 10 for me.  The DOF is superb.  Love it.', '2007-12-30 05:23:11.000000', NULL, 1),
(4344546, 625665, 82814, '<td valign="top">Wow.  Great colour and clarity.  I feel like I could reach into my computer screen and touch this.  Stunning.  This is a 10.</td>', 'Wow.  Great colour and clarity.  I feel like I could reach into my computer screen and touch this.  Stunning.  This is a 10.', '2007-12-30 05:25:15.000000', NULL, 1),
(4344551, 625749, 82814, '<td valign="top">Really like the foam of the surf in this shot, as well as the way it is enveloping the driftwood.  Excellent composition and freezing of the action.</td>', 'Really like the foam of the surf in this shot, as well as the way it is enveloping the driftwood.  Excellent composition and freezing of the action.', '2007-12-30 05:47:53.000000', NULL, 1),
(4344552, 625640, 82814, '<td valign="top">My favorite chocolate...I can taste it already.</td>', 'My favorite chocolate...I can taste it already.', '2007-12-30 05:50:22.000000', NULL, 1),
(4344553, 625748, 82814, '<td valign="top">Excellent capture and composition.</td>', 'Excellent capture and composition.', '2007-12-30 05:52:10.000000', NULL, 1),
(4344554, 625534, 82814, '<td valign="top">Superb colour and detail.  Well done.</td>', 'Superb colour and detail.  Well done.', '2007-12-30 05:52:51.000000', NULL, 1),
(4344615, 625270, 47852, '<td valign="top">I can see where you were going with this... broccoli has a great texture.  I think placing the light source more to the side would have shown off the bumps more, giving the viewer more of a feel for the texture.  As it is, we have to rely on our knowledge of how it feels.  Great choice for the background too, to really make the texture part stand out.</td>', 'I can see where you were going with this... broccoli has a great texture.  I think placing the light source more to the side would have shown off the bumps more, giving the viewer more of a feel for the texture.  As it is, we have to rely on our knowledge of how it feels.  Great choice for the background too, to really make the texture part stand out.', '2007-12-30 08:02:01.000000', NULL, 1),
(4344616, 625842, 47852, '<td valign="top">Love the variety of textures here, the long ridged petals, the fluffy part, and the tiny curlicues are all unique.  The shallow dof is great, and I like that you got all of those parts into the focused area.  The composition of the shot feels awkward to me though.  I like that you got right into the subject, but it seems sort of static.  Perhaps angling the stem a bit more to come in from the corner, and placing the focused area of textures on the rule of thirds line would help?  And I think angling the light source so it shined across the flower instead of directly onto it would help to bring out the shapes and textures even more.  Nice subject though for the challenge.</td>', 'Love the variety of textures here, the long ridged petals, the fluffy part, and the tiny curlicues are all unique.  The shallow dof is great, and I like that you got all of those parts into the focused area.  The composition of the shot feels awkward to me though.  I like that you got right into the subject, but it seems sort of static.  Perhaps angling the stem a bit more to come in from the corner, and placing the focused area of textures on the rule of thirds line would help?  And I think angling the light source so it shined across the flower instead of directly onto it would help to bring out the shapes and textures even more.  Nice subject though for the challenge.', '2007-12-30 08:08:24.000000', NULL, 1),
(4344618, 625634, 47852, '<td valign="top">The main subject blends into the background too much for my tastes.  Perhaps getting a nice tight and sharp shot of those little prickles would have been a better choice to help the viewer feel the texture?  I love the way you placed the shot on a diagonal though for both the subject and background.</td>', 'The main subject blends into the background too much for my tastes.  Perhaps getting a nice tight and sharp shot of those little prickles would have been a better choice to help the viewer feel the texture?  I love the way you placed the shot on a diagonal though for both the subject and background.', '2007-12-30 08:10:54.000000', NULL, 1),
(4344619, 625363, 47852, '<td valign="top">Love the textures (and color) of the cardboard tray against the eggs.  I can''t help but feel like that top egg is going to topple over, since it''s not leaning against that left egg!  It seems like you have just a bit of a blown out spot on the edge of the eggs there, which makes us lose the feel of the slight bumps on the egg by smoothing it out.  Perhaps just a little less or softer lighting, but the direction of the light is great.  I love how you can see the light through the pores on the darker side of the eggs.</td>', 'Love the textures (and color) of the cardboard tray against the eggs.  I can''t help but feel like that top egg is going to topple over, since it''s not leaning against that left egg!  It seems like you have just a bit of a blown out spot on the edge of the eggs there, which makes us lose the feel of the slight bumps on the egg by smoothing it out.  Perhaps just a little less or softer lighting, but the direction of the light is great.  I love how you can see the light through the pores on the darker side of the eggs.', '2007-12-30 08:14:05.000000', NULL, 1),
(4344620, 624474, 47852, '<td valign="top">Oh, what a great texture!  You can just feel the jagged, hard edges that have come from years of exposure.  The shallow dof is great here and I like the angle you took this from.  I just wish this were a bit sharper... the soft focus/blur is exactly opposite of the texture itself.</td>', 'Oh, what a great texture!  You can just feel the jagged, hard edges that have come from years of exposure.  The shallow dof is great here and I like the angle you took this from.  I just wish this were a bit sharper... the soft focus/blur is exactly opposite of the texture itself.', '2007-12-30 08:16:11.000000', NULL, 1),
(4344627, 625549, 47852, '<td valign="top">Now there are some textures! I can feel each small item just by looking at it.  Nicely arranged so that you could get all of the textures in focus, but still use a shallow dof.  Composition may be just a bit too centered for my tastes, but you definitely nailed the concept of the challenge.</td>', 'Now there are some textures! I can feel each small item just by looking at it.  Nicely arranged so that you could get all of the textures in focus, but still use a shallow dof.  Composition may be just a bit too centered for my tastes, but you definitely nailed the concept of the challenge.', '2007-12-30 08:19:53.000000', NULL, 1),
(4344639, 625589, 88287, '<td valign="top">the ant is slightly out of focus.  Otherwise I love this photo.</td>', 'the ant is slightly out of focus.  Otherwise I love this photo.', '2007-12-30 08:33:16.000000', NULL, 1),
(4344640, 625662, 47852, '<td valign="top">Great use of lighting to accentuate the textures here!</td>', 'Great use of lighting to accentuate the textures here!', '2007-12-30 08:35:52.000000', NULL, 1),
(4344643, 624547, 88287, '<td valign="top">the eye is slightly out of focus.</td>', 'the eye is slightly out of focus.', '2007-12-30 08:40:19.000000', NULL, 1),
(4344644, 624449, 88287, '<td valign="top">too contrasty, the highlights are blown.</td>', 'too contrasty, the highlights are blown.', '2007-12-30 08:41:01.000000', NULL, 1),
(4344645, 625602, 88287, '<td valign="top">needs more saturation</td>', 'needs more saturation', '2007-12-30 08:41:15.000000', NULL, 1),
(4344647, 624590, 88287, '<td valign="top">A great abstract.  What is it?!?!</td>', 'A great abstract.  What is it?!?!', '2007-12-30 08:42:30.000000', NULL, 1),
(4344650, 625643, 88287, '<td valign="top">love the photo, just wish the stripy top wasn''t there.  It''s quite distracting.</td>', 'love the photo, just wish the stripy top wasn''t there.  It''s quite distracting.', '2007-12-30 08:44:32.000000', NULL, 1),
(4344651, 625678, 79955, '<td valign="top">Nice texture from the leaf and snow , did you try just a simple vertical crop of the leaf on the right ? Would look great in my opinion (less distraction from the other leaves) - 6</td>', 'Nice texture from the leaf and snow , did you try just a simple vertical crop of the leaf on the right ? Would look great in my opinion (less distraction from the other leaves) - 6', '2007-12-30 08:44:43.000000', NULL, 1),
(4344653, 625711, 79955, '<td valign="top">great shot , nice colors , wonderful subject for the challenge. Really like the way you cropped the image - 9</td>', 'great shot , nice colors , wonderful subject for the challenge. Really like the way you cropped the image - 9', '2007-12-30 08:45:52.000000', NULL, 1),
(4344655, 625537, 88287, '<td valign="top">slightly soft focus towards the top right, where the gourds are.  Love the colours though.</td>', 'slightly soft focus towards the top right, where the gourds are.  Love the colours though.', '2007-12-30 08:46:40.000000', NULL, 1),
(4344656, 625687, 88287, '<td valign="top">The eye is out of focus.</td>', 'The eye is out of focus.', '2007-12-30 08:48:33.000000', NULL, 1),
(4344657, 624604, 47852, '<td valign="top">Great variety of textures... but wheres the big soft fluffy bath towel?</td>', 'Great variety of textures... but wheres the big soft fluffy bath towel?', '2007-12-30 08:49:24.000000', NULL, 1),
(4344660, 625748, 88287, '<td valign="top">Beautiful.  The lighting is superb.</td>', 'Beautiful.  The lighting is superb.', '2007-12-30 08:52:24.000000', NULL, 1),
(4344663, 625345, 88287, '<td valign="top">button on the bottom right spoils the composure for me?</td>', 'button on the bottom right spoils the composure for me?', '2007-12-30 08:53:45.000000', NULL, 1),
(4344666, 624930, 47852, '<td valign="top">Great texture, and the side lighting helps to bring that out even more.  I think a slight levels adjustment here to brighten it up and a slight sharpen would help to make this stand out a bit more and deepen the textures.</td>', 'Great texture, and the side lighting helps to bring that out even more.  I think a slight levels adjustment here to brighten it up and a slight sharpen would help to make this stand out a bit more and deepen the textures.', '2007-12-30 08:54:47.000000', NULL, 1),
(4344667, 625394, 88287, '<td valign="top">love it, I wonder if a thicker layer of sugar would have improved the photo?</td>', 'love it, I wonder if a thicker layer of sugar would have improved the photo?', '2007-12-30 08:55:35.000000', NULL, 1),
(4344669, 625162, 88287, '<td valign="top">Lovely!  The B&amp;W works really well.</td>', 'Lovely!  The B&W works really well.', '2007-12-30 08:56:19.000000', NULL, 1),
(4344673, 625264, 88287, '<td valign="top">I like it, I just feel that the top of the image needs to be in sharper focus.</td>', 'I like it, I just feel that the top of the image needs to be in sharper focus.', '2007-12-30 08:57:14.000000', NULL, 1),
(4344674, 625229, 79955, '<td valign="top">A little too messy - 5</td>', 'A little too messy - 5', '2007-12-30 08:57:21.000000', NULL, 1),
(4344678, 624514, 79955, '<td valign="top">nice textures , well spotted - 6</td>', 'nice textures , well spotted - 6', '2007-12-30 08:57:55.000000', NULL, 1),
(4344680, 625546, 88287, '<td valign="top">GOSH.  I love the colours.  The eye is so stark.  Makes me feel uncomfortable.</td>', 'GOSH.  I love the colours.  The eye is so stark.  Makes me feel uncomfortable.', '2007-12-30 08:59:31.000000', NULL, 1),
(4344683, 625550, 47852, '<td valign="top">What a great mix of textures... smooth, ridged, fluffy... great composition, and the water drop adds a nice focal point.  Great lighting to show off the ridges in the feather and catch the tips of the fluffy parts.  Very well done.</td>', 'What a great mix of textures... smooth, ridged, fluffy... great composition, and the water drop adds a nice focal point.  Great lighting to show off the ridges in the feather and catch the tips of the fluffy parts.  Very well done.', '2007-12-30 09:03:58.000000', NULL, 1),
(4344684, 625369, 47852, '<td valign="top">So simple, yet so much to look at.  The lines created by the intersecting boards along with the two well placed screws make a great composition.  Love the flecks of color.  All that, and you definitely captured the rough texture.  Very nicely done, I hope people don''t overlook all the hidden beauty here.</td>', 'So simple, yet so much to look at.  The lines created by the intersecting boards along with the two well placed screws make a great composition.  Love the flecks of color.  All that, and you definitely captured the rough texture.  Very nicely done, I hope people don''t overlook all the hidden beauty here.', '2007-12-30 09:04:15.000000', NULL, 1),
(4345081, 625464, 88352, '<td valign="top">Awesome shot</td>', 'Awesome shot', '2007-12-30 14:21:19.000000', NULL, 1),
(4345083, 625490, 88352, '<td valign="top">Focus is off, seems to be on the curtain behind it instead of the tree</td>', 'Focus is off, seems to be on the curtain behind it instead of the tree', '2007-12-30 14:21:56.000000', NULL, 1),
(4345086, 625799, 88352, '<td valign="top">Great close-up</td>', 'Great close-up', '2007-12-30 14:22:18.000000', NULL, 1),
(4345088, 625648, 88352, '<td valign="top">Great idea, would be better with better focus and if the focal point were not in the center of the frame.</td>', 'Great idea, would be better with better focus and if the focal point were not in the center of the frame.', '2007-12-30 14:22:58.000000', NULL, 1),
(4345090, 625468, 88352, '<td valign="top">Wow, I really like this shot, the focus is great and really shows the texture of the arc.</td>', 'Wow, I really like this shot, the focus is great and really shows the texture of the arc.', '2007-12-30 14:23:50.000000', NULL, 1),
(4345091, 625555, 88352, '<td valign="top">Seems very much like a snap-shot.  I like the idea, but needs to be developed a little more.</td>', 'Seems very much like a snap-shot.  I like the idea, but needs to be developed a little more.', '2007-12-30 14:24:54.000000', NULL, 1),
(4345092, 624839, 88352, '<td valign="top">Nice focus throughout the picture and great composition.  I like the needles from the tree in the background to create depth, but they could be blurred a little more.</td>', 'Nice focus throughout the picture and great composition.  I like the needles from the tree in the background to create depth, but they could be blurred a little more.', '2007-12-30 14:26:02.000000', NULL, 1),
(4345094, 625649, 88352, '<td valign="top">Great idea and the colors are nice, but the overall composition needs some work, the picture shouldn''t be cut in half by the horizon.</td>', 'Great idea and the colors are nice, but the overall composition needs some work, the picture shouldn''t be cut in half by the horizon.', '2007-12-30 14:26:56.000000', NULL, 1),
(4345099, 625749, 88352, '<td valign="top">Nice capture!  Great focus.</td>', 'Nice capture!  Great focus.', '2007-12-30 14:27:32.000000', NULL, 1),
(4345100, 624902, 88352, '<td valign="top">Focus is off, I can''t get a grip on what I''m seeing.</td>', 'Focus is off, I can''t get a grip on what I''m seeing.', '2007-12-30 14:28:01.000000', NULL, 1),
(4345104, 624241, 88352, '<td valign="top">I think this might have been better in color.  Here, it could be a lemon, lime, orange... The composition of the photo is nice, I like the crop.</td>', 'I think this might have been better in color.  Here, it could be a lemon, lime, orange... The composition of the photo is nice, I like the crop.', '2007-12-30 14:29:49.000000', NULL, 1),
(4345112, 624091, 88352, '<td valign="top">I really like the colors and concept, but I need a focal point to really make it a good photo.</td>', 'I really like the colors and concept, but I need a focal point to really make it a good photo.', '2007-12-30 14:35:07.000000', NULL, 1),
(4345114, 624321, 88352, '<td valign="top">Freaked me out....</td>', 'Freaked me out....', '2007-12-30 14:36:21.000000', NULL, 1),
(4345132, 625267, 88352, '<td valign="top">Very out of focus.</td>', 'Very out of focus.', '2007-12-30 14:47:17.000000', NULL, 1),
(4345135, 625836, 88352, '<td valign="top">Very nice, I like the feathers in the lower left.</td>', 'Very nice, I like the feathers in the lower left.', '2007-12-30 14:50:28.000000', NULL, 1),
(4345137, 625401, 88352, '<td valign="top">Not enough in the picture, and the focus is off.</td>', 'Not enough in the picture, and the focus is off.', '2007-12-30 14:50:53.000000', NULL, 1),
(4345138, 625696, 88352, '<td valign="top">Nice detail, but the colors seem to be off</td>', 'Nice detail, but the colors seem to be off', '2007-12-30 14:51:19.000000', NULL, 1),
