(4345147, 625139, 88352, '<td valign="top">Takes my eye through the whole photo, I really like it!</td>', 'Takes my eye through the whole photo, I really like it!', '2007-12-30 14:54:44.000000', NULL, 1),
(4345149, 624941, 88352, '<td valign="top">Interesting, seems forced.</td>', 'Interesting, seems forced.', '2007-12-30 14:55:02.000000', NULL, 1),
(4345150, 625821, 20330, '<td valign="top">i like the suhject, and the dof is great, however i would like to see more of the pebbles to see a repeated texture, its just a personal preference, i think the shot is great.</td>', 'i like the suhject, and the dof is great, however i would like to see more of the pebbles to see a repeated texture, its just a personal preference, i think the shot is great.', '2007-12-30 14:55:03.000000', NULL, 1),
