(4345393, 625337, 3087, '<td valign="top">Lovely contrast of colours and textures, really beautiful detail.</td>', 'Lovely contrast of colours and textures, really beautiful detail.', '2007-12-30 16:45:10.000000', NULL, 1),
(4345394, 625772, 3087, '<td valign="top">Such a simple image (in terms of number of elements), and yet so surreal and striking! I love the composition, with the diagonal line and the ladybird positioned just so. The shallow DOF works so well too. Nice!</td>', 'Such a simple image (in terms of number of elements), and yet so surreal and striking! I love the composition, with the diagonal line and the ladybird positioned just so. The shallow DOF works so well too. Nice!', '2007-12-30 16:46:17.000000', NULL, 1),
