(4345398, 624296, 3087, '<td valign="top">Great contrast between both colour and texture of foreground and background.</td>', 'Great contrast between both colour and texture of foreground and background.', '2007-12-30 16:47:27.000000', NULL, 1),
(4345399, 625228, 51597, '<td valign="top">Fantastic..... Terrific image..</td>', 'Fantastic..... Terrific image..', '2007-12-30 16:47:41.000000', NULL, 1),
(4345402, 625827, 3087, '<td valign="top">Lovely and so unusual to see such a tight crop and such muted colours for a Christmas decoration image. I really love the composition with the two halves and sweeping curves as well as the contrast between smooth out-of-focus ball, knobbly metal top, and the different sized "bokeh balls" (for want of a better term!). It''s all just lovely!</td>', 'Lovely and so unusual to see such a tight crop and such muted colours for a Christmas decoration image. I really love the composition with the two halves and sweeping curves as well as the contrast between smooth out-of-focus ball, knobbly metal top, and the different sized "bokeh balls" (for want of a better term!). It''s all just lovely!', '2007-12-30 16:49:16.000000', NULL, 1),
(4345405, 625630, 3087, '<td valign="top">Great textures! Strong, warm lighting and it''s resulting shadows really show off the shapes. Nice.</td>', 'Great textures! Strong, warm lighting and it''s resulting shadows really show off the shapes. Nice.', '2007-12-30 16:50:18.000000', NULL, 1),
(4345406, 625654, 74979, '<td valign="top">amazing detail and clarity and with white no less!  usually such a difficult color to capture..you''ve don eit so well.<br/>he looks a bit menacing!</td>', 'amazing detail and clarity and with white no less!  usually such a difficult color to capture..you''ve don eit so well.he looks a bit menacing!', '2007-12-30 16:50:23.000000', NULL, 1),
