(4350253, 625658, 23433, '<td valign="top">This is a cool shot, but so much is out of focus. I would have used a smaller f stop to get more focus, and more detail to the well lit areas.</td>', 'This is a cool shot, but so much is out of focus. I would have used a smaller f stop to get more focus, and more detail to the well lit areas.', '2008-01-01 15:00:06.000000', NULL, 1),
(4350592, 625550, 79720, '<td valign="top">Lovely image. The duotone is subperb, and I love the spec highlight on the waterdrop. I call front page.</td>', 'Lovely image. The duotone is subperb, and I love the spec highlight on the waterdrop. I call front page.', '2008-01-01 17:04:19.000000', NULL, 1),
(4350599, 624241, 79720, '<td valign="top">I think volour might have made this more effective.</td>', 'I think volour might have made this more effective.', '2008-01-01 17:06:16.000000', NULL, 1),
(4350606, 624718, 79720, '<td valign="top">Nice framing, lighting and colour choices.</td>', 'Nice framing, lighting and colour choices.', '2008-01-01 17:07:25.000000', NULL, 1),
(4350618, 625505, 79720, '<td valign="top">Fantastic composition, great light capture.</td>', 'Fantastic composition, great light capture.', '2008-01-01 17:09:28.000000', NULL, 1),
(4350669, 625595, 79720, '<td valign="top">Some smoke from a stick of incense? Very nicely captured. (had to edit, for clarity) -- 9.</td>', 'Some smoke from a stick of incense? Very nicely captured. (had to edit, for clarity) -- 9.', '2008-01-01 17:17:53.000000', NULL, 1),
(4351135, 625550, 61961, '<td valign="top">Subject seems like something I''ve seen too much of, but nice job on capturing the texture and on the color management.</td>', 'Subject seems like something I''ve seen too much of, but nice job on capturing the texture and on the color management.', '2008-01-01 18:56:25.000000', NULL, 1),
(4351693, 625586, 87252, '<td valign="top">Nice shot, shame there''s not more light on him!</td>', 'Nice shot, shame there''s not more light on him!', '2008-01-01 21:12:04.000000', NULL, 1),
(4351717, 624826, 61961, '<td valign="top">Can almost feel the frost on my fingertips and the edges of the leaves!  Well done.</td>', 'Can almost feel the frost on my fingertips and the edges of the leaves!  Well done.', '2008-01-01 21:18:24.000000', NULL, 1),
(4351770, 625601, 71244, '<td valign="top">extra points for the title!</td>', 'extra points for the title!', '2008-01-01 21:43:26.000000', NULL, 1),
