(4351981, 624241, 71244, '<td valign="top">nice crisp image, but, seems like color would work better here to me.</td>', 'nice crisp image, but, seems like color would work better here to me.', '2008-01-01 23:32:38.000000', NULL, 1),
(4352074, 625534, 66616, '<td valign="top">well done, knew you would do well with this one.</td>', 'well done, knew you would do well with this one.', '2008-01-02 00:03:27.000000', NULL, 0),
