(4352081, 624137, 67697, '<td valign="top">Great closesup, Lea.  I can''t believe you got a cat to sit still for this!</td>', 'Great closesup, Lea.  I can''t believe you got a cat to sit still for this!', '2008-01-02 00:04:17.000000', NULL, 0),
(4352085, 625550, 41337, '<td valign="top">Congrats Irene!</td>', 'Congrats Irene!', '2008-01-02 00:05:30.000000', NULL, 0),
(4352086, 625641, 67697, '<td valign="top">Love the earthy feel to this.  Great contrast in the natural colors.</td>', 'Love the earthy feel to this.  Great contrast in the natural colors.', '2008-01-02 00:05:36.000000', NULL, 0),
(4352088, 624590, 51750, '<td valign="top">Dam i thought this would''ve done better!</td>', 'Dam i thought this would''ve done better!', '2008-01-02 00:05:59.000000', NULL, 0),
(4352094, 625800, 67697, '<td valign="top">You are giving a lot of props to sand bags lol.  I never would have known.  What a great macro!  Excellent capture of texture as well.</td>', 'You are giving a lot of props to sand bags lol.  I never would have known.  What a great macro!  Excellent capture of texture as well.', '2008-01-02 00:07:30.000000', NULL, 0),
(4352097, 625683, 56880, '<td valign="top">I stand my Tiger''s goopy eyes--it''s a sign of age (I think he''s like 16), wisdom, and natural beauty.  And the goop has texture too!  Look at that contrast between smooth goop and detailed fur.<br/> <br/>Besides, this cat wouldn''t let me get close enough to him to de-goop him.</td>', 'I stand my Tiger''s goopy eyes--it''s a sign of age (I think he''s like 16), wisdom, and natural beauty.  And the goop has texture too!  Look at that contrast between smooth goop and detailed fur. Besides, this cat wouldn''t let me get close enough to him to de-goop him.', '2008-01-02 00:08:19.000000', NULL, 0),
(4352100, 625678, 67697, '<td valign="top">Wow Charlene, what an interesting find!  These things do look like wet fur.  Great catch on the detail in the snow too.</td>', 'Wow Charlene, what an interesting find!  These things do look like wet fur.  Great catch on the detail in the snow too.', '2008-01-02 00:09:39.000000', NULL, 0),
(4352103, 625665, 41337, '<td valign="top">"6... probably less"? This from the king of top tens??? LOL. Congrats on the HM!</td>', '"6... probably less"? This from the king of top tens??? LOL. Congrats on the HM!', '2008-01-02 00:10:13.000000', NULL, 0),
(4352104, 624137, 63495, '<td valign="top">congrats on a great close up and a great score.</td>', 'congrats on a great close up and a great score.', '2008-01-02 00:10:45.000000', NULL, 0),
(4352106, 625683, 67697, '<td valign="top">I like the DOF.  It really helps draw attention to the nose and eyes.  He looks kind of angry lol.</td>', 'I like the DOF.  It really helps draw attention to the nose and eyes.  He looks kind of angry lol.', '2008-01-02 00:10:53.000000', NULL, 0),
(4352113, 625641, 63495, '<td valign="top">nice textures, shot looks very peaceful to me.</td>', 'nice textures, shot looks very peaceful to me.', '2008-01-02 00:13:23.000000', NULL, 0),
(4352118, 625188, 67697, '<td valign="top">Very cool.  It looks like there''s a bunch of little hands hanging down from the branches.</td>', 'Very cool.  It looks like there''s a bunch of little hands hanging down from the branches.', '2008-01-02 00:14:24.000000', NULL, 0),
(4352119, 625505, 41337, '<td valign="top">Congrats on your ribbon, Mr. Sandman! :)</td>', 'Congrats on your ribbon, Mr. Sandman! :)', '2008-01-02 00:14:39.000000', NULL, 0),
(4352120, 625537, 70514, '<td valign="top">The colors and lighting are just beautiful. Great finish, lovely image.</td>', 'The colors and lighting are just beautiful. Great finish, lovely image.', '2008-01-02 00:15:01.000000', NULL, 0),
