(4356666, 625162, 52549, '<td valign="top">Great shot, Richard. Wonderful lighting. Congrats on top 10.</td>', 'Great shot, Richard. Wonderful lighting. Congrats on top 10.', '2008-01-03 08:34:18.000000', NULL, 0),
