(4357938, 625800, 40797, '<td valign="top">Wonderful textures Deb!! I LOVE this.</td>', 'Wonderful textures Deb!! I LOVE this.', '2008-01-03 15:48:18.000000', NULL, 0),
(4358207, 625267, 42198, '<td valign="top">You''re never going to be able to hand-hold a camera with a shutter-speed of 1/4 second. You''ll need to support it either on a tripod, or on a pile of books or something solid.</td>', 'You''re never going to be able to hand-hold a camera with a shutter-speed of 1/4 second. You''ll need to support it either on a tripod, or on a pile of books or something solid.', '2008-01-03 17:28:04.000000', NULL, 0),
