(4366048, 625544, 15305, '<td valign="top">I''m so sorry for the DQ.  :-(<br/></td>', 'I''m so sorry for the DQ.  :-(', '2008-01-06 12:23:41.000000', NULL, 0),
(4366513, 625711, 47852, '<td valign="top">Great closeup shot with a nice capture of the textures of the leaf.  As another commenter noted, the focus falling off at the edges doesn''t seem to help the shot for me.  I think if I had any other suggestions, it would be to have tilted the leaf just a bit more clockwise, so that the main vein was more diagonal, but being careful not to make the most focused area going completely horizontal.  Anyway, nice shot and congrats on your new PB!</td>', 'Great closeup shot with a nice capture of the textures of the leaf.  As another commenter noted, the focus falling off at the edges doesn''t seem to help the shot for me.  I think if I had any other suggestions, it would be to have tilted the leaf just a bit more clockwise, so that the main vein was more diagonal, but being careful not to make the most focused area going completely horizontal.  Anyway, nice shot and congrats on your new PB!', '2008-01-06 14:51:22.000000', NULL, 0),
(4366690, 625014, 66384, '<td valign="top">Beautiful macro. I love the colors, DOF, and tack sharp focus on the tack sharp subject. I like the diagonal line too.</td>', 'Beautiful macro. I love the colors, DOF, and tack sharp focus on the tack sharp subject. I like the diagonal line too.', '2008-01-06 16:14:58.000000', NULL, 0),
(4367292, 625544, 56417, '<td valign="top">So sorry about this Laurie. Not really i understand it either....there will be other top 5''s i''m sure....; )</td>', 'So sorry about this Laurie. Not really i understand it either....there will be other top 5''s i''m sure....; )', '2008-01-06 20:40:54.000000', NULL, 0),
(4367435, 625544, 48697, '<td valign="top">Sorry to see you got DQ''ed. Bummer luck, still a cool shot, congrats on a nice image.</td>', 'Sorry to see you got DQ''ed. Bummer luck, still a cool shot, congrats on a nice image.', '2008-01-06 21:12:07.000000', NULL, 0);
